style.css:
/* Общие настройки для body */
body {
    background-color: #2e003e; /* Темно-фиолетовый цвет */
    color: #ffffff; /* Белый цвет текста для контраста */
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    overflow: hidden;
}

/* Фон с гифкой */
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: url('https://i.gifer.com/g32K.gif'); /* Замените ссылку на нужную гифку */
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    opacity: 0.4; /* Прозрачность гифки, чтобы не отвлекала */
    z-index: -1; /* Чтобы гифка была на заднем плане */
}

/* Настройки заголовков */
h1, h2, h3, h4, h5, h6 {
    color: #e0b3ff; /* Светлый лавандовый цвет для заголовков */
}

/* Настройки ссылок */
a {
    color: #d9a6ff; /* Цвет ссылок */
    text-decoration: none;
}

a:hover {
    color: #f0e6ff; /* При наведении */
    text-decoration: underline;
}

/* Настройки кнопок */
button {
    background-color: #4d1a73; /* Темно-фиолетовый цвет кнопок */
    color: #ffffff; /* Белый текст */
    border: none;
    padding: 10px 20px;
    cursor: pointer;
    border-radius: 5px;
}

button:hover {
    background-color: #6a239b; /* При наведении мыши */
}

/* Настройка текстовых полей */
input[type="text"], textarea {
    background-color: #36134d; /* Фон полей ввода */
    color: #ffffff; /* Цвет текста */
    border: 1px solid #563d7c;
    padding: 10px;
    border-radius: 5px;
}

/* Для панели навигации */
nav {
    background-color: #3a104f; /* Темно-фиолетовый фон панели навигации */
    padding: 15px;
    text-align: center;
}

nav a {
    color: #d9a6ff;
    padding: 10px 20px;
}

nav a:hover {
    color: #ffffff;
}

/* Анимация для элементов */
button, a, input[type="text"], textarea {
    transition: background-color 0.3s ease, color 0.3s ease;
}
